-- DESCRIBE and SHOW as a subquery
SELECT * FROM (DESCRIBE tbl);
SELECT * FROM (DESCRIBE SELECT * FROM tbl) AS d;
CREATE TABLE tbl_description AS SELECT * FROM (DESCRIBE tbl);
INSERT INTO tbl_description DESCRIBE tbl;
SELECT * FROM (SHOW TABLES);
SELECT * FROM (SHOW ALL TABLES) AS t;
